// Normalize scraper / UI payload into Logic Engine input
// Accepts webhook body wrapper or flat JSON (chained from url-scraper Extract Content)
const root = items[0].json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;

const raw_text = body.raw_text || body.text || body.content || '';
const source_url = body.source_url || body.url || 'Unknown';
const goal = body.goal || body.user_goal || '';

if (!raw_text || String(raw_text).trim().length < 20) {
  throw new Error('Logic Engine requires raw_text (scraped site content).');
}

// Light clean aligned with prompts/cleaning-utils.md (strip script/style noise)
const cleaned_text = String(raw_text)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 12000);

return { raw_text: String(raw_text), source_url: String(source_url), goal: String(goal), cleaned_text };

