// Parse Claude Messages API → strategic JSON (prompts/reasoning-claude.md schema)
const resp = items[0].json;
let text = '';
if (resp.content && Array.isArray(resp.content)) {
  text = resp.content.map(p => p.text || '').join('\n');
} else if (typeof resp.text === 'string') {
  text = resp.text;
}

const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
const candidate = (fenced ? fenced[1] : text).trim();
let strategy;
try { strategy = JSON.parse(candidate); }
catch (e) { throw new Error('Claude did not return parseable JSON: ' + e.message); }

const upstream = $('Normalize + Light Clean').first().json;
return {
  source_url: upstream.source_url,
  goal: upstream.goal,
  positioning: strategy.positioning || {},
  gaps: strategy.gaps || {},
  ui_guidance: strategy.ui_guidance || {},
  strategy
};

