// Merge Claude + GPT into artifact-generator Schema Mapper shape
const gptResp = items[0].json;
let content = gptResp.choices?.[0]?.message?.content || gptResp.text || '';
if (typeof content !== 'string') content = JSON.stringify(content);

const fenced = content.match(/```(?:json)?\s*([\s\S]*?)```/);
const candidate = (fenced ? fenced[1] : content).trim();
let creation;
try { creation = JSON.parse(candidate); }
catch (e) { throw new Error('GPT did not return parseable JSON: ' + e.message); }

const strategy = $('Parse Claude JSON').first().json;

const merged = {
  positioning: strategy.positioning,
  gaps: strategy.gaps,
  ui_guidance: strategy.ui_guidance,
  monetization: creation.monetization,
  offerStack: creation.offerStack,
  speedToMarket: creation.speedToMarket,
  source_url: strategy.source_url
};

// `text` path supports Schema Mapper: input.text ? JSON.parse(input.text) : input
return { ...merged, text: JSON.stringify(merged) };
